#include <cstdint>
static inline uint32_t
popcount_swar(uint32_t n) {
    // Count the bits independently in each 4-bit group.
    n = n - ((n >> 1) & 0x77777777u)
          - ((n >> 2) & 0x33333333u)
          - ((n >> 3) & 0x11111111u);

    // Combine each pair of nibble counts, then sum the four byte counts.
    n = (n + (n >> 4)) & 0x0F0F0F0Fu;
    return (n * 0x01010101u) >> 24;
}
